test('UI exports favorites and imports them through both merge and replace',async()=>{
 const app=ui(withBlocks());let exported;
 try{app.change('draw-cars','2');app.get('drag-places').dispatchEvent(new app.w.KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true,cancelable:true}));app.get('generate').click();app.get('lock-cars').click();app.get('lock-cars:1').click();app.get('favorite-result').click();app.get('show-favorites').click();app.get('rename-favorite-'+app.saved().favorites[0].id).click();app.input('favorite-name','Backup favorite');app.get('favorite-name-form').dispatchEvent(new app.w.Event('submit',{cancelable:true,bubbles:true}));app.w.Blob=class{constructor(parts){this.text=parts.join('');}};app.w.URL.createObjectURL=blob=>{exported=blob.text;return 'blob:test';};app.w.URL.revokeObjectURL=()=>{};app.w.HTMLAnchorElement.prototype.click=()=>{};app.get('export-backup').click();const backup=C.parseBackup(exported);assert.equal(backup.favorites.length,1);assert.equal(backup.favorites[0].name,'Backup favorite');assert.equal(backup.recentResults.length,1);assert.equal(backup.setups[0].lockedPicks[0].listId,'cars');assert.equal(backup.setups[0].lockedPicks[1].slot,1);assert.equal(C.drawCount(backup.setups[0],'cars'),2);assert.deepEqual(plain(backup.setups[0].listOrder),['cars','places','cities']);
  for(const mode of ['merge','replace']){const restored=ui(make());try{Object.defineProperty(restored.get('backup-file'),'files',{value:[{name:'example.json',size:exported.length,text:async()=>exported}],configurable:true});restored.get('backup-file').dispatchEvent(new restored.w.Event('change'));await new Promise(resolve=>setImmediate(resolve));assert.match(restored.get('backup-summary').textContent,/1 favorites/);restored.d.querySelector(`input[name="backup-mode"][value="${mode}"]`).checked=true;restored.get('backup-apply').click();const saved=restored.saved();assert.equal(saved.favorites[0].text,backup.favorites[0].text);assert.equal(saved.favorites[0].name,'Backup favorite');assert.equal(saved.recentResults.length,1);assert.equal(saved.setups.length,mode==='merge'?4:2);assert.ok(C.validate(saved));const imported=saved.setups[mode==='merge'?2:0];assert.equal(imported.drawCounts[0].count,2);assert.equal(imported.lockedPicks[1].slot,1);assert.deepEqual(imported.listOrder.slice(0,3),[saved.lists[mode==='merge'?3:0].id,saved.lists[mode==='merge'?4:1].id,saved.lists[mode==='merge'?5:2].id]);}finally{restored.dom.window.close();}}
 }finally{app.dom.window.close();}
});
