test('reordering a filtered view changes only visible slots and preserves all hidden positions',()=>{
 const s=make(),a=s.setups[0];a.listOrder=['cars','places','cities'];C.setDrawCount(a,'cars',2);const r=C.generate(s,a,()=>0);C.recordResult(s,a,r);C.toggleLock(s,a,r.picks[1]);const other=JSON.stringify(s.setups[1]),snapshot=JSON.stringify(a.lastResult),locks=JSON.stringify(a.lockedPicks),counts=JSON.stringify(a.drawCounts);
 assert.equal(C.reorderList(a,'cars','cities',['cars','cities'],true),true);assert.deepEqual(plain(a.listOrder),['cities','places','cars']);assert.deepEqual(plain(a.listIds),['cities','cars']);assert.equal(JSON.stringify(a.lastResult),snapshot);assert.equal(JSON.stringify(a.lockedPicks),locks);assert.equal(JSON.stringify(a.drawCounts),counts);assert.equal(JSON.stringify(s.setups[1]),other);
 const restored=C.parseBackup(JSON.stringify(s));assert.deepEqual(plain(restored.setups[0].listOrder),['cities','places','cars']);C.selectList(restored.setups[0],'places',true);assert.deepEqual(plain(restored.setups[0].listIds),['cities','places','cars']);assert.equal(C.generate(restored,restored.setups[0],()=>0).picks[1].listId,'places');
});
test('drag insertion and keyboard movement share full-order and filtered-order semantics',()=>{
 const a=make().setups[0];a.listOrder=['a','h1','b','h2','c','h3','d'];a.listIds=['a','b','c','d'];
 C.reorderList(a,'a','c',['a','b','c','d'],true);assert.deepEqual(plain(a.listOrder),['b','h1','c','h2','a','h3','d']);C.reorderList(a,'d','b',['b','c','a','d']);assert.deepEqual(plain(a.listOrder),['d','h1','b','h2','c','h3','a']);C.moveList(a,'a',-3,['d','b','c','a']);assert.deepEqual(plain(a.listOrder),['a','h1','d','h2','b','h3','c']);
 C.moveList(a,'a',1);assert.deepEqual(plain(a.listOrder),['h1','a','d','h2','b','h3','c']);assert.deepEqual(plain(a.listIds),['a','d','b','c']);
});
test('reordering ignores invalid, unchanged and out-of-view targets without corrupting order',()=>{
 const a=make().setups[0],before=JSON.stringify(a);
 for(const args of [['cars','cars',['cars','cities']],['cars','places',['cars','cities']],['missing','cities',['cars','cities']],['cars','cities',['cars','cities'],false]])assert.equal(C.reorderList(a,...args),false);
 assert.equal(C.moveList(a,'cars',-1,['cars','cities']),false);assert.equal(JSON.stringify(a),before);
 assert.equal(C.reorderList(a,'cars','cities',['missing','cars','cars','cities'],true),true);assert.deepEqual(plain(a.listOrder),['cities','cars','places']);
});

function managementFixture(){const s=make();s.lists=[{id:'a',name:'Scene A',items:['Alpha','Apple']},{id:'h1',name:'Hidden one',items:['One']},{id:'b',name:'Scene B',items:['Beta','Banana']},{id:'h2',name:'Hidden two',items:['Two']},{id:'c',name:'Scene C',items:['Gamma','Grape']}];for(const a of s.setups){a.listOrder=s.lists.map(l=>l.id);a.listIds=['a','b','c'];}C.setDrawCount(s.setups[0],'a',2);return s;}
const displayedLists=app=>[...app.d.querySelectorAll('#list-rows .list-row')].map(n=>n.dataset.listId);
function key(app,id,key){app.get(id).dispatchEvent(new app.w.KeyboardEvent('keydown',{key,bubbles:true,cancelable:true}));}
function pointer(app,target,type,x,y,id=1){const event=new app.w.Event(type,{bubbles:true,cancelable:true});Object.assign(event,{pointerId:id,button:0,isPrimary:true,clientX:x,clientY:y});target.dispatchEvent(event);return event;}
function mockRows(app){app.get('list-rows').getBoundingClientRect=()=>({left:0,right:320,top:100,bottom:400,width:320,height:300});[...app.d.querySelectorAll('#list-rows .list-row')].forEach((row,i)=>row.getBoundingClientRect=()=>({left:0,right:320,top:100+i*50,bottom:150+i*50,width:320,height:50}));}
test('All and Selected are display-only filters and compact rows keep editing and counts accessible',()=>{
 const app=ui(managementFixture());try{app.get('generate').click();app.get('lock-a').click();const before=app.saved();assert.equal(app.get('list-view-all').textContent,'All (5)');assert.equal(app.get('list-view-selected').textContent,'Selected (3)');app.get('list-view-selected').click();assert.deepEqual(displayedLists(app),['a','b','c']);assert.deepEqual(app.saved(),before);assert.equal(app.get('list-view-selected').getAttribute('aria-pressed'),'true');assert.equal(app.d.querySelectorAll('.list-preview').length,0);assert.equal(app.get('draw-a').value,'2');assert.equal(app.get('lock-a').getAttribute('aria-pressed'),'true');app.d.querySelector('[aria-label="Edit Scene A"]').click();assert.equal(app.get('list-items').value,'Alpha\nApple');app.get('list-cancel').click();app.get('list-view-all').click();assert.deepEqual(displayedLists(app),['a','h1','b','h2','c']);assert.deepEqual(app.saved(),before);}finally{app.dom.window.close();}
});
test('keyboard and position picker reorder selected rows while hidden slots survive switching views and reload',()=>{
 const app=ui(managementFixture());try{app.get('list-view-selected').click();key(app,'drag-a','End');assert.deepEqual(displayedLists(app),['b','c','a']);assert.equal(app.d.activeElement.id,'drag-a');assert.deepEqual(app.saved().setups[0].listOrder,['b','h1','c','h2','a']);app.get('drag-a').click();assert.equal(app.get('move-list-dialog').open,true);assert.equal(app.get('move-list-position').options.length,3);app.change('move-list-position','b');app.get('move-list-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(app.get('move-list-dialog').open,false);assert.deepEqual(displayedLists(app),['a','b','c']);key(app,'drag-c','Home');const saved=app.saved();assert.deepEqual(saved.setups[0].listOrder,['c','h1','a','h2','b']);const reloaded=ui(saved);try{assert.deepEqual(displayedLists(reloaded),['c','h1','a','h2','b']);assert.equal(reloaded.get('list-view-all').getAttribute('aria-pressed'),'true');reloaded.change('check-h1',true);assert.deepEqual(reloaded.saved().setups[0].listIds,['c','h1','a','b']);}finally{reloaded.dom.window.close();}}finally{app.dom.window.close();}
});
test('search and Selected combine without moving omitted rows or changing generated selections',()=>{
 const app=ui(managementFixture());try{const before=app.saved();app.input('list-search','Scene');key(app,'drag-c','Home');assert.deepEqual(app.saved().setups[0].listOrder,['c','h1','a','h2','b']);app.get('list-view-selected').click();app.input('list-search','Hidden');assert.equal(displayedLists(app).length,0);assert.match(app.get('list-rows').textContent,/No lists match/);app.get('list-view-all').click();assert.deepEqual(displayedLists(app),['h1','h2']);app.get('generate').click();assert.deepEqual(app.saved().setups[0].lastResult.picks.map(p=>p.listId),['c','a','a','b']);assert.deepEqual(app.saved().setups[0].drawCounts,before.setups[0].drawCounts);}finally{app.dom.window.close();}
});
test('unchecking the last visible selection leaves a way back to the full library and keeps positions',()=>{
 const app=ui(managementFixture());try{app.get('list-view-selected').click();for(const id of ['a','b','c'])app.change('check-'+id,false);assert.deepEqual(displayedLists(app),[]);assert.equal(app.get('list-view-selected').textContent,'Selected (0)');assert.equal(app.d.activeElement.id,'list-view-all');assert.match(app.get('list-rows').textContent,/No lists are selected/);app.d.querySelector('#list-rows button').click();assert.deepEqual(displayedLists(app),['a','h1','b','h2','c']);app.change('check-b',true);assert.deepEqual(app.saved().setups[0].listOrder,['a','h1','b','h2','c']);assert.equal(app.get('draw-a').value,'2');}finally{app.dom.window.close();}
});
test('pointer dragging reorders selected rows on release and preserves hidden slots and locked results',()=>{
 const app=ui(managementFixture());try{app.get('generate').click();app.get('lock-a:1').click();app.get('list-view-selected').click();mockRows(app);const before=app.saved(),handle=app.get('drag-a');pointer(app,handle,'pointerdown',14,120);pointer(app,app.d,'pointermove',14,240);assert.equal(app.d.body.classList.contains('list-dragging'),true);assert.ok(app.d.querySelector('[data-list-id="c"]').classList.contains('drop-after'));assert.deepEqual(app.saved(),before);pointer(app,app.d,'pointerup',14,240);const saved=app.saved();assert.deepEqual(saved.setups[0].listOrder,['b','h1','c','h2','a']);assert.deepEqual(saved.setups[0].lastResult,before.setups[0].lastResult);assert.deepEqual(saved.setups[0].lockedPicks,before.setups[0].lockedPicks);assert.equal(app.d.querySelectorAll('.drop-after,.drop-before,.dragging').length,0);assert.equal(app.d.activeElement.id,'drag-a');app.get('drag-a').dispatchEvent(new app.w.MouseEvent('click',{detail:1,bubbles:true,cancelable:true}));assert.equal(app.get('move-list-dialog').open,false);}finally{app.dom.window.close();}
});
test('cancelled, outside, and unrelated pointer drags leave saved order unchanged',()=>{
 for(const cancel of ['Escape','pointercancel','outside','other-pointer']){const app=ui(managementFixture());try{app.get('list-view-selected').click();mockRows(app);const before=app.saved();pointer(app,app.get('drag-a'),'pointerdown',14,120);pointer(app,app.d,'pointermove',14,240,cancel==='other-pointer'?2:1);if(cancel==='Escape')key(app,'drag-a','Escape');else if(cancel==='pointercancel')pointer(app,app.d,'pointercancel',14,240);else if(cancel==='outside')pointer(app,app.d,'pointermove',500,240);pointer(app,app.d,'pointerup',14,240);assert.deepEqual(app.saved(),before);assert.equal(app.d.body.classList.contains('list-dragging'),false);}finally{app.dom.window.close();}}
});
test('position picker cancel and keyboard boundaries do not reorder or alter other setups',()=>{
 const app=ui(managementFixture());try{const before=app.saved();key(app,'drag-a','ArrowUp');key(app,'drag-c','ArrowDown');app.get('drag-a').click();app.change('move-list-position','c');app.get('move-list-cancel').click();assert.deepEqual(app.saved(),before);app.get('drag-a').click();app.change('move-list-position','c');app.get('move-list-form').dispatchEvent(new app.w.Event('submit',{bubbles:true,cancelable:true}));assert.deepEqual(app.saved().setups[0].listOrder,['h1','b','h2','c','a']);assert.deepEqual(app.saved().setups[1],before.setups[1]);}finally{app.dom.window.close();}
});
test('dragging near the list edge scrolls toward offscreen rows and cancels its animation cleanly',()=>{
 const s=managementFixture();for(let i=0;i<20;i++)s.lists.push({id:'extra-'+i,name:'Extra '+i,items:['Item']});C.syncLists(s);const app=ui(s);
 try{let nextFrame=null,cancelled=false;app.w.requestAnimationFrame=callback=>{nextFrame=callback;return 42;};app.w.cancelAnimationFrame=id=>{if(id===42){cancelled=true;nextFrame=null;}};const container=app.get('list-rows');container.getBoundingClientRect=()=>({left:0,right:320,top:100,bottom:400,width:320,height:300});[...container.querySelectorAll('.list-row')].forEach((row,i)=>row.getBoundingClientRect=()=>({left:0,right:320,top:100+i*50-container.scrollTop,bottom:150+i*50-container.scrollTop,width:320,height:50}));const before=app.saved();pointer(app,app.get('drag-a'),'pointerdown',14,120);pointer(app,app.d,'pointermove',14,395);assert.equal(typeof nextFrame,'function');nextFrame();assert.ok(container.scrollTop>0);assert.deepEqual(app.saved(),before);key(app,'drag-a','Escape');assert.equal(cancelled,true);assert.equal(nextFrame,null);assert.equal(app.d.body.classList.contains('list-dragging'),false);assert.deepEqual(app.saved(),before);}finally{app.dom.window.close();}
});
